    const n = big ? 200000 : r.int(1, 8);
    const m = big ? 200000 : r.int(0, Math.min(8, (n * (n - 1)) / 2));
    const seen = new Set(), roads = [];
    while (roads.length < m) {
      const u = r.int(0, n - 1), v = r.int(0, n - 1);
      if (u === v) continue;
      const k = Math.min(u, v) * n + Math.max(u, v);
      if (seen.has(k)) continue;
      seen.add(k);
      roads.push([u, v]);
    }
    return [n, roads, r.int(0, n - 1), r.int(0, n - 1)];
  }

