function canTravel(n: number, roads: number[][], start: number, goal: number): boolean {
  const reached = new Array(n).fill(false);
  reached[start] = true;
  let changed = true;
  while (changed) {
    changed = false;
    for (const [u, v] of roads) {
      if (reached[u] !== reached[v]) { reached[u] = reached[v] = true; changed = true; }
    }
  }
  return reached[goal];
}

