function canTravel(n: number, roads: number[][], start: number, goal: number): boolean {
  if (start === goal) return true;
  const adj: number[][] = Array.from({ length: n }, () => []);
  for (const [u, v] of roads) { adj[u].push(v); adj[v].push(u); }
  const seen = new Array(n).fill(false);
  const queue = [start];
  seen[start] = true;
  for (let h = 0; h < queue.length; h++) {
    for (const nb of adj[queue[h]]) {
      if (seen[nb]) continue;
      if (nb === goal) return true;
      seen[nb] = true;
      queue.push(nb);
    }
  }
  return false;
}

